package io.github.classgraph.issues.issue804;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import io.github.classgraph.ClassGraph;
import io.github.classgraph.ScanResult;

/**
 * Issue 804.
 */
public class Issue804Test {

    private static final String NESTED_EXAMPLE_CLASS = "org.springframework.util.ResourceUtils";

    @Test
    void scanningNestedJarsInPathsContainingSpacesShouldNeverFail(@TempDir final Path tempDir) throws IOException {
        final var targetJar = createSpringBootJarInExampleDirectory(tempDir, "directory with spaces");

        try (var scanResult = scanJar(targetJar)) {
            assertThat(scanResult.getClassInfo(NESTED_EXAMPLE_CLASS)).isNotNull();
        }
    }

    @Test
    void scanningNestedJarsInPathsContainingHashesShouldNeverFail(@TempDir final Path tempDir) throws IOException {
        final var targetJar = createSpringBootJarInExampleDirectory(tempDir, "directory-without-spaces#123");

        try (var scanResult = scanJar(targetJar)) {
            assertThat(scanResult.getClassInfo(NESTED_EXAMPLE_CLASS)).isNotNull();
        }
    }

    @Test
    void scanningNestedJarsInPathsContainingSpacesAndHashesShouldNeverFail(@TempDir final Path tempDir)
            throws IOException {
        final var targetJar = createSpringBootJarInExampleDirectory(tempDir, "directory with spaces #123");

        try (var scanResult = scanJar(targetJar)) {
            assertThat(scanResult.getClassInfo(NESTED_EXAMPLE_CLASS)).isNotNull();
        }
    }

    private Path createSpringBootJarInExampleDirectory(final Path temporaryDirectory, final String directoryName)
            throws IOException {
        final var directoryWithSpaces = temporaryDirectory.resolve(directoryName);
        Files.createDirectories(directoryWithSpaces);
        final var nestedJar = directoryWithSpaces.resolve("spring-boot-fully-executable-jar.jar");
        try (var nestedJarsExample = Issue804Test.class.getClassLoader()
                .getResourceAsStream("spring-boot-fully-executable-jar.jar")) {
            Files.copy(nestedJarsExample, nestedJar);
        }
        return nestedJar;
    }

    private ScanResult scanJar(final Path targetJar) {
        return new ClassGraph().enableClassInfo().overrideClasspath(targetJar.toUri()).scan();
    }

}

package io.github.classgraph.issues.issue914;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.lang.annotation.Annotation;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

import org.junit.jupiter.api.Test;

import io.github.classgraph.ClassGraph;
import io.github.classgraph.ClassInfo;
import io.github.classgraph.ScanResult;

/**
 * Test {@link ClassInfo#getMethodInfoWithAnnotation(String)} and friends (issue
 * #914).
 */
public class Issue914Test {

    /**
     * A method annotation. Also targets {@code ANNOTATION_TYPE}, so that it can
     * meta-annotate {@link MetaMarker}.
     */
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ ElementType.METHOD, ElementType.FIELD, ElementType.ANNOTATION_TYPE })
    public @interface Marker {
    }

    /**
     * A meta-annotated annotation, to check that meta-annotations are matched too.
     */
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ ElementType.METHOD, ElementType.FIELD })
    @Marker
    public @interface MetaMarker {
    }

    /** An unrelated annotation, which should never be matched. */
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ ElementType.METHOD, ElementType.FIELD })
    public @interface Unrelated {
    }

    /**
     * Superclass, so that declared vs. inherited methods and fields can be
     * distinguished.
     */
    public static class Super {
        @Marker
        public int superField;

        @Unrelated
        public int unmarkedSuperField;

        @Marker
        public void superMarked() {
        }

        @Unrelated
        public void superUnmarked() {
        }
    }

    /** Subclass. */
    public static class Sub extends Super {
        @Marker
        public int subField;

        @MetaMarker
        public int metaMarkedField;

        public int unannotatedField;

        @Marker
        public void subMarked() {
        }

        @MetaMarker
        public void subMetaMarked() {
        }

        public void unannotated() {
        }
    }

    private static final String MARKER = Marker.class.getName();

    /**
     * Scan this test's classes.
     *
     * @return the scan result.
     */
    private static ScanResult scan() {
        return new ClassGraph().acceptPackages(Issue914Test.class.getPackage().getName()).enableMethodInfo()
                .enableFieldInfo().enableAnnotationInfo().scan();
    }

    /**
     * Declared methods with the annotation should not include methods declared by
     * the superclass.
     */
    @Test
    public void declaredMethodInfoWithAnnotation() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getDeclaredMethodInfoWithAnnotation(MARKER).getNames())
                    .containsExactlyInAnyOrder("subMarked", "subMetaMarked");
        }
    }

    /**
     * Methods with the annotation should include methods declared by the
     * superclass.
     */
    @Test
    public void methodInfoWithAnnotation() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getMethodInfoWithAnnotation(MARKER).getNames()).containsExactlyInAnyOrder("subMarked",
                    "subMetaMarked", "superMarked");
        }
    }

    /**
     * The {@link Class}-typed overloads should behave identically to the
     * {@link String}-typed overloads.
     */
    @Test
    public void classOverloadsMatchStringOverloads() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getMethodInfoWithAnnotation(Marker.class).getNames())
                    .isEqualTo(sub.getMethodInfoWithAnnotation(MARKER).getNames());
            assertThat(sub.getDeclaredMethodInfoWithAnnotation(Marker.class).getNames())
                    .isEqualTo(sub.getDeclaredMethodInfoWithAnnotation(MARKER).getNames());
            assertThat(sub.getFieldInfoWithAnnotation(Marker.class).getNames())
                    .isEqualTo(sub.getFieldInfoWithAnnotation(MARKER).getNames());
            assertThat(sub.getDeclaredFieldInfoWithAnnotation(Marker.class).getNames())
                    .isEqualTo(sub.getDeclaredFieldInfoWithAnnotation(MARKER).getNames());
        }
    }

    /** An annotation that no method has should produce the empty list, not null. */
    @Test
    public void unmatchedAnnotationYieldsEmptyList() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getMethodInfoWithAnnotation("com.xyz.NonExistentAnnotation")).isEmpty();
            assertThat(sub.getFieldInfoWithAnnotation("com.xyz.NonExistentAnnotation")).isEmpty();
        }
    }

    /** Constructors are excluded, matching {@link ClassInfo#getMethodInfo()}. */
    @Test
    public void constructorsAreExcluded() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getMethodInfoWithAnnotation(MARKER).getNames()).doesNotContain("<init>");
        }
    }

    /**
     * Declared fields with the annotation should not include fields declared by the
     * superclass.
     */
    @Test
    public void declaredFieldInfoWithAnnotation() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getDeclaredFieldInfoWithAnnotation(MARKER).getNames()).containsExactlyInAnyOrder("subField",
                    "metaMarkedField");
        }
    }

    /**
     * Fields with the annotation should include fields declared by the superclass.
     */
    @Test
    public void fieldInfoWithAnnotation() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThat(sub.getFieldInfoWithAnnotation(MARKER).getNames()).containsExactlyInAnyOrder("subField",
                    "metaMarkedField", "superField");
        }
    }

    /** Passing a non-annotation {@link Class} should be rejected. */
    @Test
    public void nonAnnotationClassIsRejected() {
        try (var scanResult = scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            @SuppressWarnings("unchecked")
            final Class<? extends Annotation> notAnAnnotation = (Class<? extends Annotation>) (Class<?>) String.class;
            assertThatThrownBy(() -> sub.getMethodInfoWithAnnotation(notAnAnnotation))
                    .isInstanceOf(IllegalArgumentException.class);
            assertThatThrownBy(() -> sub.getFieldInfoWithAnnotation(notAnAnnotation))
                    .isInstanceOf(IllegalArgumentException.class);
        }
    }

    /**
     * Without {@code enableAnnotationInfo()}, an {@link IllegalArgumentException}
     * should be thrown.
     */
    @Test
    public void annotationInfoMustBeEnabled() {
        try (var scanResult = new ClassGraph().acceptPackages(Issue914Test.class.getPackage().getName())
                .enableMethodInfo().enableFieldInfo().scan()) {
            final var sub = scanResult.getClassInfo(Sub.class.getName());
            assertThatThrownBy(() -> sub.getMethodInfoWithAnnotation(MARKER))
                    .isInstanceOf(IllegalArgumentException.class);
            assertThatThrownBy(() -> sub.getFieldInfoWithAnnotation(MARKER))
                    .isInstanceOf(IllegalArgumentException.class);
        }
    }
}

package io.github.classgraph.issues.issue916;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

import io.github.classgraph.ClassGraph;
import io.github.classgraph.Resource;
import io.github.classgraph.ScanResult;

/**
 * Issue 916: calling {@link ClassGraph#removeTemporaryFilesAfterScan()} closed
 * the whole {@code NestedJarHandler} -- every open slice and the inflater
 * recycler -- before the {@link ScanResult} was returned. Any subsequent read
 * of a resource, or load of a class whose bytes had to come from a jar, then
 * failed, even though {@link ScanResult#isClosed()} still reported
 * {@code false}, and even for an ordinary jar that never needed a temporary
 * file in the first place.
 */
public class Issue916Test {
    /**
     * A plain, non-nested jar creates no temporary files, so nothing needs to be
     * closed to remove them.
     */
    @Test
    public void resourcesAreStillReadableAfterRemoveTemporaryFilesAfterScan() throws Exception {
        final var jarURL = Issue916Test.class.getResource("/issue286.jar");
        try (var scanResult = new ClassGraph().overrideClasspath(jarURL).enableClassInfo()
                .removeTemporaryFilesAfterScan().scan()) {
            assertThat(scanResult.isClosed()).isFalse();
            assertThat(scanResult.getAllResources()).isNotEmpty();
            for (final Resource resource : scanResult.getAllResources()) {
                // Previously threw IOException("Already closed")
                assertThat(resource.load()).isNotNull();
            }
        }
    }

    /**
     * Without the flag, resources were always readable -- pin that this is
     * unchanged.
     */
    @Test
    public void resourcesAreReadableWithoutTheFlag() throws Exception {
        final var jarURL = Issue916Test.class.getResource("/issue286.jar");
        try (var scanResult = new ClassGraph().overrideClasspath(jarURL).enableClassInfo().scan()) {
            for (final Resource resource : scanResult.getAllResources()) {
                assertThat(resource.load()).isNotNull();
            }
        }
    }
}

package io.github.classgraph.issues.issue930;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;

import java.lang.annotation.Annotation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;

import org.junit.jupiter.api.Test;

import io.github.classgraph.ClassGraph;
import io.github.classgraph.ScanResult;

/**
 * Issue 930: calling {@code equals()} on an annotation instance returned by
 * {@code AnnotationInfo#loadClassAndInstantiate()} threw a
 * {@link NullPointerException} once the {@link ScanResult} it came from had
 * been closed.
 *
 * <p>
 * {@code ScanResult#close()} sets {@code ScanResult#reflectionUtils} to null
 * but leaves {@code AnnotationInfo#scanResult} pointing at the closed
 * {@code ScanResult}, so the guard
 * {@code scanResult == null ? new ReflectionUtils() : scanResult.reflectionUtils}
 * yielded null rather than falling back to a fresh {@code ReflectionUtils}.
 */
public class Issue930Test {
    /**
     * An annotation with a parameter, so that {@code equals()} has to reflectively
     * read a parameter value.
     */
    @Retention(RetentionPolicy.RUNTIME)
    public @interface Issue930Annotation {
        /**
         * The annotation value.
         *
         * @return the value
         */
        String value();
    }

    /** A class annotated with {@link Issue930Annotation}. */
    @Issue930Annotation("abc")
    public static class Annotated {
    }

    /**
     * An annotation instance obtained from a {@link ScanResult} must remain usable
     * after that {@link ScanResult} has been closed.
     */
    @Test
    public void annotationEqualsWorksAfterScanResultIsClosed() {
        final Annotation proxyAnnotation;
        try (var scanResult = new ClassGraph().acceptPackages(Issue930Test.class.getPackage().getName()).enableAllInfo()
                .scan()) {
            final var classInfo = scanResult.getClassInfo(Annotated.class.getName());
            assertThat(classInfo).isNotNull();
            proxyAnnotation = classInfo.getAnnotationInfo(Issue930Annotation.class).loadClassAndInstantiate();
            assertThat(proxyAnnotation).isNotNull();
        }

        // The ScanResult is now closed, so ScanResult#reflectionUtils is null.
        final Annotation jdkAnnotation = Annotated.class.getAnnotation(Issue930Annotation.class);
        assertThatCode(() -> proxyAnnotation.equals(jdkAnnotation)).doesNotThrowAnyException();
        assertThat(proxyAnnotation.equals(jdkAnnotation)).isTrue();
    }
}

package io.github.classgraph.json;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;

import org.junit.jupiter.api.Test;

import io.github.classgraph.ClassGraph;
import io.github.classgraph.ScanResult;

/**
 */
public class AnnotationDefaultVals {
    @Retention(RetentionPolicy.RUNTIME)
    @interface MyAnnotation {
        String msg() default "hello";
    }

    @MyAnnotation
    class MyClass {
    }

    /**
     * Test serialize then deserialize scan result.
     */
    @Test
    public void testSerializeThenDeserializeWithAnnotation() {
        // Get URL base for overriding classpath (otherwise the JSON representation of
        // the ScanResult won't be
        // the same after the first and second deserialization, because
        // overrideClasspath is set by the first
        // serialization for consistency.)
        final var classfileURL = getClass().getClassLoader()
                .getResource(AnnotationDefaultVals.class.getName().replace('.', '/') + ".class").toString();
        final var classpathBase = classfileURL.substring(0,
                classfileURL.length() - (AnnotationDefaultVals.class.getName().length() + 6));
        try (var scanResult = new ClassGraph().overrideClasspath(classpathBase)
                .acceptPackagesNonRecursive(AnnotationDefaultVals.class.getPackage().getName()).ignoreClassVisibility()
                .enableAllInfo().scan()) {
            assertThat(scanResult.getClassInfo(MyClass.class.getName()).getAnnotationInfo().get(0)
                    .getDefaultParameterValues().get(0).getValue()).isEqualTo("hello");
            final var indent = 2;
            final var scanResultJSON = scanResult.toJSON(indent);
            try (var scanResultDeserialized = ScanResult.fromJSON(scanResultJSON)) {
                final var scanResultReserializedJSON = scanResultDeserialized.toJSON(indent);
                assertThat(scanResultReserializedJSON).isEqualTo(scanResultJSON);
                assertThat(scanResultDeserialized.getClassInfo(MyClass.class.getName()).getAnnotationInfo().get(0)
                        .getDefaultParameterValues().get(0).getValue()).isEqualTo("hello");
            }
        }
    }
}

