            this.y = y;
        }
    }

    /**
     * The Class B.
     *
     * @param <V> the value type
     */
    private static class B<V> {

        /** The b. */
        V b;

        /**
         * Constructor.
         */
        @SuppressWarnings("null")
        public B() {
        }

        /**
         * Constructor.
         *
         * @param q the q
         */
        public B(final V q) {
            this.b = q;
        }
    }

    /**
     * The Class C.
     *
     * @param <T> the generic type
     */
    private static class C<T> extends B<T> {

        /** The a. */
        A<List<T>, String> a;

        /** The arr. */
        T[] arr;

        /**
         * Constructor.
         */
        public C() {
        }

        /**
         * Constructor.
         *
         * @param t the t
         */
        public C(final T t) {
            super(t);
            final List<T> tList = new ArrayList<>();
            tList.add(t);
            a = new A<>(tList, "x");
            final List<T> ts = new ArrayList<>();
            ts.add(t);
            ts.add(t);
            ts.add(t);
            @SuppressWarnings("unchecked")
            final var a = (T[]) ts.toArray();
            arr = a;
        }
    }

    /**
     * The Class D.
     *
     * @param <T> the generic type
     */
    private static class D<T> {

        /** The z. */
        T z;

        /** The q. */
        C<T> q;

        /** The map. */
        Map<T, T> map = new HashMap<>();

        /** The list. */
        List<T> list;

        /**
         * Constructor.
         */
        @SuppressWarnings("null")
        public D() {
        }

        /**
         * Constructor.
         *
         * @param obj the obj
         */
        public D(final T obj) {
            z = obj;
            q = new C<>(obj);
            map.put(obj, obj);
            list = new ArrayList<>();
            list.add(obj);
            list.add(obj);
            list.add(obj);
        }
    }

    /**
     * The Class E.
     */
    private static class E extends D<Short> {

        /** The c. */
        C<Integer> c = new C<>(5);

        /** The z. */
        int z = 42;

        /**
         * Constructor.
         */
        public E() {
        }

        /**
         * Constructor.
         *
         * @param obj the obj
         */
        public E(final Short obj) {
            super(obj);
        }
    }

    /**
     * The Class F.
     */
    private static class F extends D<Float> {

        /** The wxy. */
        int wxy = 123;

        /**
         * Constructor.
         */
        public F() {
        }

        /**
         * Constructor.
         *
         * @param f the f
         */
        public F(final Float f) {
            super(f);
        }
    }

    /**
     * The Class G.
     */
    private static class G {

        /** The e. */
        E e = new E((short) 3);

        /** The f. */
        F f = new F(1.5f);
    }

    /**
     * The Class H.
     */
    private static class H {

        /** The g. */
        G g;
    }

    /**
     * Test JSON.
     */
    @Test
    public void testJSON() {
        final var h = new H();
        h.g = new G();

        final var reflectionUtils = new ReflectionUtils();
        final var json0 = JSONSerializer.serializeFromField(h, "g", 0, false);

        final var expected = //
                "{\"e\":{\"list\":[3,3,3],\"map\":{\"3\":3},\"q\":{\"b\":3,\"a\":{\"x\":[3],\"y\":\"x\"},"
                        + "\"arr\":[3,3,3]}," + "\"c\":{\"b\":5,\"a\":{\"x\":[5],\"y\":\"x\"},\"arr\":[5,5,5]},"
                        + "\"z\":42},\"f\":{\"list\":[1.5,1.5,1.5],\"map\":{\"1.5\":1.5}," + "\"q\":{\"b\":1.5,"
                        + "\"a\":{\"x\":[1.5],\"y\":\"x\"},\"arr\":[1.5,1.5,1.5]},\"z\":1.5,\"wxy\":123}}";

        assertThat(json0).isEqualTo(expected);

        final var obj = JSONDeserializer.deserializeObject(G.class, json0);

        final var json1 = JSONSerializer.serializeObject(obj, 0, false);

